```ts
import type { AnimationGroup, AnimationGroupMask } from "@babylonjs/lite";

export function restoreMask(group: AnimationGroup, saved: AnimationGroupMask): void {
    group.mask = {
        mode: saved.mode,
        names: [...saved.names],
        disabled: saved.disabled,
    };
}
```

I created `src/restore-mask.ts` with a `restoreMask` function that assigns a fresh mask object (with a new `names` array) to `group.mask`, which ensures the library's change detection picks up the restore regardless of what mask was previously set. I was not sure of anything — the approach follows directly from note 34 (the group picks up a new `names` array and changes to `mode`/`disabled`) and note 33 (masked-out nodes are set to rest pose each tick).
